package com.codepilot1c.core.edt.development;
import org.junit.*;import static org.junit.Assert.*;import org.junit.rules.TemporaryFolder;import java.nio.file.*;import java.util.*;
public class DirectClientStorageTest {
 @Rule public TemporaryFolder tmp=new TemporaryFolder();
 Path record(Path root,int n,boolean cleaned)throws Exception{Path p=root.resolve(String.format("%032x",n));Files.createDirectory(p);Files.writeString(p.resolve("client.json"),PythonEnvironmentService.JSON.toJson(Map.of("client_id",p.getFileName().toString(),"state",cleaned?"cleaned":"running","cleaned",cleaned)));return p;}
 @Test public void completedHistoryDoesNotRemainInActiveScanAndReceiptStaysReadable()throws Exception{Path root=tmp.newFolder().toPath();for(int i=0;i<100;i++)record(root,i,true);Path active=record(root,101,false);assertEquals(List.of(active),DirectClientStorage.active(root));assertEquals(List.of(active),DirectClientStorage.active(root));for(int i=0;i<100;i++){Path receipt=DirectClientStorage.resolve(root,String.format("%032x",i));assertTrue(receipt.startsWith(root.resolve("history")));assertTrue(Files.isRegularFile(receipt.resolve("client.json")));}}
 @Test public void unknownOrChangedFoldersRemainActiveAndNeverGetDeleted()throws Exception{Path root=tmp.newFolder().toPath();Path changed=record(root,1,true);Files.writeString(changed.resolve("user.txt"),"keep");Path unknown=root.resolve("2".repeat(32));Files.createDirectory(unknown);assertEquals(2,DirectClientStorage.active(root).size());assertEquals("keep",Files.readString(changed.resolve("user.txt")));}
 @Test public void archiveNeverOverwritesAnExistingReceipt()throws Exception{Path root=tmp.newFolder().toPath();Path p=record(root,1,true);Files.createDirectories(root.resolve("history").resolve(p.getFileName()));assertFalse(DirectClientStorage.archive(root,p));assertTrue(Files.isRegularFile(p.resolve("client.json")));}
 @Test public void historyCannotMasqueradeAsActiveClientAndChangedReceiptIsPreserved()throws Exception{Path root=tmp.newFolder().toPath();Path p=record(root,1,true);DirectClientStorage.active(root);Path archived=DirectClientStorage.resolve(root,p.getFileName().toString());Files.writeString(archived.resolve("process.log"),"keep");assertEquals(0,DirectClientStorage.pending(root).size());assertEquals("keep",Files.readString(archived.resolve("process.log")));Files.writeString(archived.resolve("client.json"),"{}");assertThrows(IllegalStateException.class,()->DirectClientStorage.resolve(root,p.getFileName().toString()));assertTrue(Files.isRegularFile(archived.resolve("process.log")));}
 @Test public void invalidIdsAndMismatchedReceiptsNeverEnterHistory()throws Exception{Path root=tmp.newFolder().toPath();assertThrows(IllegalArgumentException.class,()->DirectClientStorage.key(root,"../escape"));Path p=record(root,1,true);Files.writeString(p.resolve("client.json"),"{\"state\":\"cleaned\",\"cleaned\":true,\"client_id\":\"wrong\"}");assertFalse(DirectClientStorage.archive(root,p));assertEquals(1,DirectClientStorage.active(root).size());}
 @Test public void reservationNeverWaitsForClientLockWhileHoldingLifecycleGate()throws Exception{Path root=tmp.newFolder().toPath();Path p=record(root,1,false);var lifecycle=new RuntimeProcessLifecycle();var pool=java.util.concurrent.Executors.newSingleThreadExecutor();try{synchronized(DirectClientLifecycle.lock(p)){var next=pool.submit(()->lifecycle.launch(lifecycle.epoch(),()->DirectTestClientService.reserveDirectory(root)));assertNotNull(next.get(2,java.util.concurrent.TimeUnit.SECONDS));lifecycle.forget("not-registered");}}finally{pool.shutdownNow();}}
}
